package com.hereliesaz.graffitixr.common.azphalt

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Pins the K-M reference to the fixture that `core/wgpu-engine/tests/pigment.rs` feeds the WGSL port,
 * so the two implementations are compared on identical pigments and mixtures. The fixture is
 * regenerated by deleting it and running this test; a diff in review is the signal that the model changed.
 */
class PigmentGoldenFixtureTest {
    private val path = File("../wgpu-engine/tests/fixtures/pigment_golden.txt")

    private fun render(): String {
        val set = PlaceholderPigments.set
        val n = set.pigments.size
        val lines = ArrayList<String>()
        lines += "# pigment golden fixture: P id K0..K6 S0..S6 / M c0..c${n - 1} | linear r g b (placeholder data)"
        for (p in set.pigments) lines += "P ${p.id} " + (p.K + p.S).joinToString(" ")
        var seed = 987654321L
        fun rnd(): Float { seed = seed * 6364136223846793005L + 1442695040888963407L; return ((seed ushr 33) % 1000) / 1000f }
        val mixtures = ArrayList<FloatArray>()
        for (i in 0 until n) mixtures += FloatArray(n).also { it[i] = 1f }
        repeat(36) {
            val c = FloatArray(n)
            val k = 2 + (rnd() * 3).toInt()
            repeat(k) { c[(rnd() * n).toInt().coerceAtMost(n - 1)] += 0.05f + rnd() }
            mixtures += c
        }
        for (c in mixtures) {
            val rgb = PigmentMixer.mixLinearRgb(c, set.pigments)
            lines += "M " + c.joinToString(" ") + " | " + rgb.joinToString(" ")
        }
        return lines.joinToString("\n") + "\n"
    }

    @Test
    fun theFixtureMatchesTheReference() {
        val want = render()
        if (!path.exists()) {
            path.parentFile.mkdirs()
            path.writeText(want)
        }
        assertEquals(want, path.readText(), "pigment_golden.txt is stale: delete it and re-run this test to regenerate")
        assertTrue(want.lines().count { it.startsWith("M ") } >= 40)
    }
}
